ruleBookInfo.intro:
@js:
var d = (typeof result === 'string') ? JSON.parse(result) : result;
var ci = d.data.comicInfo;
function arr(li) {
  var s = [];
  for (var i = 0; i < li.length; i++) { s.push(li[i].tagName); }
  return s.join(' / ');
}
var out = '';
out += '  🎯 状态：' + (arr(ci.statusTagList || []) || '未知') + '\n';
out += '🔥 人气：' + (ci.hotNumStr || ci.hotNum || '?') + '\n';
out += '📜 简介：\n' + (ci.description || '暂无简介');
result = out;

