ruleExplore.bookList:
@js:
var d = (typeof result === 'string') ? JSON.parse(result) : result;
var list = d.data.comicList || d.data || [];
var out = [];
for (var i = 0; i < list.length; i++) {
  var x = list[i];
  out.push(JSON.stringify({
    _name: x.name || x.title || '',
    _author: x.authors || '',
    _cover: x.cover || '',
    _kind: x.types || '',
    _intro: '状态：' + (x.status || '') + String.fromCharCode(10) + '更新：' + (x.last_update_chapter_name || ''),
    _last: x.last_update_chapter_name || '',
    _py: x.comic_py || x.comicId || ''
  }));
}
result = out;

